from typing_extensions import Annotated
from ...common import BaseRequestModel

class DiscoveryCrossExaminationRequest(BaseRequestModel):
    input: str
    topic: str
    target: str
    topic_question: str


class DiscoveryCrossExaminationOutput(BaseRequestModel):
    topic: str
    answer: Annotated[
        str,
        ...,
        "The argument that refutes topic_question generated by the agent"
    ]